describe('Stale Data Invalidation After Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should invalidate stale data after successful form submission', () => {
    // Intercept the initial GET request to fetch stale data
    cy.intercept('GET', '/api/data').as('getInitialData');
    cy.wait('@getInitialData');

    // Verify stale data is displayed
    cy.get('[data-testid="data-value"]').should('contain', 'Stale Data');

    // Intercept the form submission API call
    cy.intercept('POST', '/api/submit-form').as('submitForm');

    // Fill out the form
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-input"]').type('This is a test message');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the form submission API call
    cy.wait('@submitForm');

    // Intercept the data refresh call
    cy.intercept('GET', '/api/data').as('getRefreshedData');
    cy.wait('@getRefreshedData');

    // Verify stale data is replaced with fresh data
    cy.get('[data-testid="data-value"]').should('contain', 'Fresh Data');
    cy.get('[data-testid="data-timestamp"]').should('be.visible');
    cy.get('[data-testid="data-timestamp"]').should('not.contain', 'Stale Data');
  });

  it('should handle form submission failure and not invalidate data', () => {
    // Intercept the initial GET request to fetch stale data
    cy.intercept('GET', '/api/data').as('getInitialData');
    cy.wait('@getInitialData');

    // Verify stale data is displayed
    cy.get('[data-testid="data-value"]').should('contain', 'Stale Data');

    // Intercept the form submission API call and make it fail
    cy.intercept('POST', '/api/submit-form', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('submitFormFailed');

    // Fill out the form
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-input"]').type('Another test message');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the failed form submission API call
    cy.wait('@submitFormFailed');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Server error');

    // Verify stale data is still displayed
    cy.get('[data-testid="data-value"]').should('contain', 'Stale Data');
    cy.get('[data-testid="data-timestamp"]').should('be.visible');
  });
});
